"""Helpers for converting musical pitches to FT2 notes with the right sample source."""

import math

# Empirical formula: y(N) = 0.0112 * 2^(N/12) is the playback ratio
# playback_hz = source_hz * y(N)
# Solve for N: N = 12 * log2(playback_hz / (source_hz * 0.0112))

def y(note):
    """Playback ratio for given FT2 note."""
    return 0.0112 * (2 ** (note / 12.0))

def target_for_note(note, source_hz):
    return source_hz * y(note)

def note_for_target(target_hz, source_hz):
    if target_hz <= 0: return None
    return 12.0 * math.log2(target_hz / (source_hz * 0.0112))

def round_note(target_hz, source_hz):
    return round(note_for_target(target_hz, source_hz))

# Standard instrument mappings
DRUM_NOTE = 36  # ignore pitch for drums
BASS_SOURCE = 1238.0
LEAD_SOURCE = 2476.0
PAD_SOURCE  = 1238.0
PLUCK_SOURCE = 4952.0
SUB_SOURCE  = 1238.0
STAB_SOURCE = 4952.0

def bass_note(midi_pitch_offset_from_a1):
    """Return FT2 note for playing a bass note at given pitch (relative to A1=55Hz)."""
    # A1 = 55Hz
    return round_note(55 * 2 ** (midi_pitch_offset_from_a1 / 12.0), BASS_SOURCE)

def lead_note(midi_semitone_offset):
    """Return FT2 note for lead at given offset from A4 (440Hz)."""
    return round_note(440 * 2 ** (midi_semitone_offset / 12.0), LEAD_SOURCE)

def pad_note(midi_semitone_offset):
    """Return FT2 note for pad at given offset from A2 (110Hz)."""
    return round_note(110 * 2 ** (midi_semitone_offset / 12.0), PAD_SOURCE)

def pluck_note(midi_semitone_offset):
    """Return FT2 note for pluck at given offset from A4 (440Hz)."""
    return round_note(440 * 2 ** (midi_semitone_offset / 12.0), PLUCK_SOURCE)

# Scale degrees in A minor (semitone offsets from A)
A_MINOR = {
    'A': 0, 'B': 2, 'C': 3, 'D': 5, 'E': 7, 'F': 8, 'G': 10
}

# Octave offsets
def octave(o):
    return 12 * o

# Common bass notes in A minor context (relative to A1=55Hz)
def bass_pitch(name, oct_shift=0):
    return A_MINOR[name] + octave(oct_shift)

# Lead notes (relative to A4=440Hz)
def lead_pitch(name, oct_shift=0):
    return A_MINOR[name] + octave(2 + oct_shift)  # A4 = 2 octaves above A2 = 24 semitones

# Pad notes (relative to A2=110Hz)
def pad_pitch(name, oct_shift=0):
    return A_MINOR[name] + octave(oct_shift)

# Test computation
if __name__ == "__main__":
    print("Bass notes (around A1=55Hz):")
    for name in ['A', 'C', 'D', 'E', 'F', 'G']:
        for oct_shift in [0, 1, 2]:
            offset = A_MINOR[name] + 12*oct_shift
            n = bass_note(offset)
            actual_f = BASS_SOURCE * y(n)
            print(f"  {name}+{oct_shift*12} -> FT2 note {n} -> {actual_f:.1f}Hz")
    print("\nLead notes (around A4):")
    for name in ['A', 'B', 'C', 'D', 'E', 'F', 'G']:
        for oct_shift in [-1, 0, 1]:
            offset = A_MINOR[name] + 12*oct_shift
            n = lead_note(offset)
            actual_f = LEAD_SOURCE * y(n)
            print(f"  {name}+{oct_shift*12} -> FT2 note {n} -> {actual_f:.1f}Hz")
    print("\nPad notes (around A2):")
    for name in ['A', 'C', 'E', 'F', 'G']:
        for oct_shift in [0, 1]:
            offset = A_MINOR[name] + 12*oct_shift
            n = pad_note(offset)
            actual_f = PAD_SOURCE * y(n)
            print(f"  {name}+{oct_shift*12} -> FT2 note {n} -> {actual_f:.1f}Hz")
    print("\nPluck notes (around A4):")
    for name in ['A', 'B', 'C', 'D', 'E', 'F', 'G']:
        for oct_shift in [0, 1, 2]:
            offset = A_MINOR[name] + 12*oct_shift
            n = pluck_note(offset)
            actual_f = PLUCK_SOURCE * y(n)
            print(f"  {name}+{oct_shift*12} -> FT2 note {n} -> {actual_f:.1f}Hz")
PYEOF
